import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CZrxoOIU.js";const m=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/old/index.md","filePath":"en/old/readme.md","lastUpdated":1719120541000}'),o={name:"en/old/index.md"};function s(r,e,l,c,p,d){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>You are viewing the documentation for the old versions of <code>WebApiClient.JIT</code> and <code>WebApiClient.AOT</code>.<br> There will be no new feature updates, and we cannot guarantee quick bug fixes.<br> We recommend migrating to the new version, <code>WebApiClientCore</code>, as soon as possible.</p></div><h2 id="webapiclient-jit" tabindex="-1">WebApiClient.JIT <a class="header-anchor" href="#webapiclient-jit" aria-label="Permalink to &quot;WebApiClient.JIT&quot;">​</a></h2><p>Creates proxy classes for HTTP request interfaces at runtime using Emit. When calling HttpApiClient.Create(), a proxy class for TInterface is created in a new assembly with the same class name and namespace as TInterface. Since the proxy class and TInterface are not in the same assembly, TInterface must be public.</p><ul><li>Can be directly referenced in the project by including WebApiClient.JIT.dll;</li><li>Not suitable for platforms that do not support JIT technology (iOS, UWP);</li><li>The interface must be public.</li></ul><h2 id="webapiclient-aot" tabindex="-1">WebApiClient.AOT <a class="header-anchor" href="#webapiclient-aot" aria-label="Permalink to &quot;WebApiClient.AOT&quot;">​</a></h2><p>Modifies the compiled assembly using Mono.Cecil during the compilation process to insert IL instructions for proxy classes of HTTP request interfaces. This step is done before the AOT compilation phase. The assembly, module, and namespace of the proxy type are the same as the interface type, and its name is the interface type name with a $ prefix. These proxy classes can be seen by inspecting the compiled assembly using a decompiler.</p><ul><li>The project must install WebApiClient.AOT via NuGet to work properly;</li><li>No JIT, supports a wide range of platforms;</li><li>The interface does not need to be public and can be nested within a class.</li></ul>',8)])])}const b=t(o,[["render",s]]);export{m as __pageData,b as default};
